11","mediaId":"6ac3fc2c1aa14a97bd46a19c","sortOrder":10},{"altText":"Fern Cottage photo 12","mediaId":"6ac3fc2d1aa14a97bd46a19d","sortOrder":11},{"altText":"Fern Cottage photo 13","mediaId":"6ac3fc2f1aa14a97bd46a19e","sortOrder":12}]', '[{"kind":"image","altText":"Fern Cottage photo 2","mediaId":"6ac3fc1e1aa14a97bd46a193","sortOrder":0},{"kind":"image","altText":"Fern Cottage photo 1","mediaId":"6ac3fc1d1aa14a97bd46a192","sortOrder":1},{"kind":"image","altText":"Fern Cottage photo 3","mediaId":"6ac3fc201aa14a97bd46a194","sortOrder":2},{"kind":"image","altText":"Fern Cottage photo 4","mediaId":"6ac3fc211aa14a97bd46a195","sortOrder":3},{"kind":"image","altText":"Fern Cottage photo 5","mediaId":"6ac3fc231aa14a97bd46a196","sortOrder":4},{"kind":"image","altText":"Fern Cottage photo 6","mediaId":"6ac3fc241aa14a97bd46a197","sortOrder":5},{"kind":"image","altText":"Fern Cottage photo 7","mediaId":"6ac3fc261aa14a97bd46a198","sortOrder":6},{"kind":"image","altText":"Fern Cottage photo 8","mediaId":"6ac3fc271aa14a97bd46a199","sortOrder":7},{"kind":"image","altText":"Fern Cottage photo 9","mediaId":"6ac3fc291aa14a97bd46a19a","sortOrder":8},{"kind":"image","altText":"Fern Cottage photo 10","mediaId":"6ac3fc2a1aa14a97bd46a19b","sortOrder":9},{"kind":"image","altText":"Fern Cottage photo 11","mediaId":"6ac3fc2c1aa14a97bd46a19c","sortOrder":10},{"kind":"image","altText":"Fern Cottage photo 12","mediaId":"6ac3fc2d1aa14a97bd46a19d","sortOrder":11},{"kind":"image","altText":"Fern Cottage photo 13","mediaId":"6ac3fc2f1aa14a97bd46a19e","sortOrder":12}]', '<h3>Welcome to Fern Cottage<br><br><a href="https://hamptworthstays.com/uploads/media/2026/10/a8a03cac-whatsapp-image-2026-10-29-at-12-13-12-am.jpg">https://hamptworthstays.com/uploads/media/2026/10/a8a03cac-whatsapp-image-2026-10-29-at-12-13-12-am.jpg</a></h3>', '<p><strong>Ground floor:</strong> open-plan kitchen/diner, lounge with wood burner, ground floor bedroom with ensuite.</p><p><strong>First floor:</strong> two further bedrooms and family bathroom.</p><ul><li>Electric hob &amp; oven</li><li>Washer/dryer</li><li>Garden furniture</li></ul>', '["6acb6e5ca458b0c2bef54ef3"]', 'Home Farm, Hamptworth, Salisbury SP5 2DU — on the Hampshire/Wiltshire border, minutes from Hamptworth Golf & Country Club.', '<p>Information correct at the time of writing:-</p><p>The cottages at Home Farm are conveniently located on the border with Wiltshire and Hampshire, so there are lots of opportunities for things to do and days out.</p><p>Enjoy the facilities at <strong>Hamptworth Golf &amp; Country Club</strong> — Championship golf course, padel, pickleball and clubhouse restaurant.</p><p>Explore the <a href="https://www.newforestnpa.gov.uk/" target="_blank">New Forest National Park</a> — walk or cycle through ancient woodland and spot free-roaming ponies.</p><p>Discover <a href="https://www.salisburycathedral.org.uk/" target="_blank">Salisbury Cathedral</a>, home to the tallest spire in Britain and the Magna Carta.</p><p>Visit the iconic <a href="https://www.english-heritage.org.uk/visit/places/stonehenge/" target="_blank">Stonehenge</a> and <a href="https://www.nationaltrust.org.uk/visit/wiltshire/stourhead" target="_blank">Stourhead gardens</a>.</p>', 50.9622, -1.7347, NULL, 1, 'Each cottage includes a complimentary welcome hamper with a selection of teas, coffee, fresh milk and biscuits for guests to enjoy during their stay.', NULL, '<p>Each cottage includes a complimentary welcome hamper with a selection of teas, coffee, fresh milk and biscuits for guests to enjoy during their stay.</p>', '["6ac3e2bced148dd299f90fb0","6ac3e2bced148dd299f90fb1","6ac3e2bced148dd299f90fb2","6ac3e2bced148dd299f90fb3","6ac3e2bced148dd299f90fb4","6ac3e2bced148dd299f90fb5","6ac3e2bced148dd299f90fb7","6ac3e2bded148dd299f90fb8","6ac3e2bded148dd299f90fb9","6ac3ece4f55bc9c9731d99e3","6ac3e2bbed148dd299f90fa7","6ac3e2bbed148dd299f90fa8","6ac3e2bbed148dd299f90fa9","6ac3e2bbed148dd299f90faa","6ac3e2bbed148dd299f90fab","6ac3e2bbed148dd299f90fac","6ac3e2bced148dd299f90fae","6ac3e2bced148dd299f90fad","6ac3e2bced148dd299f90faf","6ac3e2bced148dd299f90fb6","6ac3e2bded148dd299f90fba","1af5d93f980aec69f00aa837","f6632456e87c9c5265df2836"]', '[{"url":"https://www.newforestnpa.gov.uk/","name":"New Forest National Park","description":"Walking & cycling","imageMediaId":"6ac4fd9dffefee1267f07f06"},{"url":null,"name":"Hamptworth Golf & Country Club","description":"Golf, dining & clubhouse","imageMediaId":null},{"url":"https://www.salisburycathedral.org.uk/","name":"Salisbury Cathedral","description":"Historic landmark","imageMediaId":null},{"url":"https://www.english-heritage.org.uk/visit/places/stonehenge/","name":"Stonehenge","description":"World heritage site","imageMediaId":null}]', 3, 2, NULL, 'ACTIVE', NULL, '2026-10-05 19:46:27.000', '2026-10-31 14:34:29.000') ON DUPLICATE KEY UPDATE `property_id`=VALUES(`property_id`), `name`=VALUES(`name`), `slug`=VALUES(`slug`), `short_description`=VALUES(`short_description`), `description`=VALUES(`description`), `max_adults`=VALUES(`max_adults`), `max_children`=VALUES(`max_children`), `max_occupancy`=VALUES(`max_occupancy`), `beds`=VALUES(`beds`), `amenities`=VALUES(`amenities`), `images`=VALUES(`images`), `media`=VALUES(`media`), `property_details_html`=VALUES(`property_details_html`), `layout_html`=VALUES(`layout_html`), `floorplan_media_ids`=VALUES(`floorplan_media_ids`), `location_text`=VALUES(`location_text`), `surroundings_html`=VALUES(`surroundings_html`), `map_lat`=VALUES(`map_lat`), `map_lng`=VALUES(`map_lng`), `map_embed_url`=VALUES(`map_embed_url`), `welcome_hamper_included`=VALUES(`welcome_hamper_included`), `welcome_hamper_description`=VALUES(`welcome_hamper_description`), `welcome_hamper_image_media_id`=VALUES(`welcome_hamper_image_media_id`), `welcome_hamper_html`=VALUES(`welcome_hamper_html`), `amenity_ids`=VALUES(`amenity_ids`), `nearby_attractions`=VALUES(`nearby_attractions`), `bedrooms`=VALUES(`bedrooms`), `bathrooms`=VALUES(`bathrooms`), `max_dogs